"% Clear workspace
clear; clc; close all;

% 1. Define Nominal Longitudinal Model
% States x = [u; w; q; theta]
V = 690.0;   % ft/s
Xu = -0.007;
Xw = 0.045;
Zu = -0.04;
Zw = -0.8;
Mw = -0.0062;
Mq = -1.05;
g = 32.174;

% State Matrix A
A = [Xu, Xw, 0, -g;
     Zu, Zw, V, 0;
     0,  Mw, Mq, 0;
     0,  0,  1, 0];

% Input Matrix B
B = [0; -6.5; -5.0; 0];

% 2. Design Feedback Gain K
% Desired Short-Period poles
wn_sp = 2.3;
zeta_sp = 0.58;
desired_sp_poles = roots([1, 2*zeta_sp*wn_sp, wn_sp^2]);

% Get Open-Loop Poles
ol_poles = eig(A);

% Identify Phugoid poles (slowest 2)
[~, idx] = sort(abs(ol_poles), 'ascend');
phugoid_poles = ol_poles(idx(1:2));

% Target poles: Keep Phugoid at open-loop, place SP at desired
target_poles = [phugoid_poles; desired_sp_poles];

% Calculate K using pole placement
% Check controllability
if rank(ctrb(A,B)) < 4
    error('System is not controllable.');
end
K = place(A, B, target_poles);

% 3. Monte Carlo Simulation
N = 200;
pct = 0.30;

% Generate deterministic random samples for uncertain parameters
% f_Mw
rng(20260829);
f_Mw = 1 + pct * (2 * rand(N, 1) - 1);

% f_Zw
rng(20261829);
f_Zw = 1 + pct * (2 * rand(N, 1) - 1);

% f_Mq
rng(20262829);
f_Mq = 1 + pct * (2 * rand(N, 1) - 1);

% Initialize counter
count_pass = 0;

% Loop over N samples
for i = 1:N
    % Construct perturbed A matrix
    A_pert = A;
    A_pert(2,2) = Zw * f_Zw(i); % Zw
    A_pert(3,2) = Mw * f_Mw(i); % Mw
    A_pert(3,3) = Mq * f_Mq(i); % Mq

    % Compute Closed-Loop Poles
    cl_poles = eig(A_pert - B * K);

    % Identify Short-Period poles (the two fastest poles with largest magnitude)
    [~, idx_fast] = sort(abs(cl_poles), 'descend');
    sp_poles = cl_poles(idx_fast(1:2));

    % Calculate Natural Frequency (wn) and Damping Ratio (zeta)
    % For a complex pair p1, p2: wn = sqrt(p1*p2), zeta = -real(p1+p2)/(2*wn)
    % This formula generalizes to real roots as well.
    p1 = sp_poles(1);
    p2 = sp_poles(2);

    wn_curr = sqrt(abs(p1 * p2));
    sum_p = p1 + p2;
    zeta_curr = -real(sum_p) / (2 * wn_curr);

    % Check specifications
    if (wn_curr >= 2.2 && wn_curr <= 2.4) && (zeta_curr >= 0.55)
        count_pass = count_pass + 1;
    end
end

% 4. Prepare Results
pass_fraction = count_pass / N;
failing_case_count = N - count_pass;

% Create result struct
resultStruct = struct();
resultStruct.pass_fraction = pass_fraction;
resultStruct.failing_case_count = failing_case_count;

% Write to result.json
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(resultStruct));
fclose(fid);"
